package com.example.proyectolp.controller;
import com.example.proyectolp.config.AppConfig;import com.example.proyectolp.model.*;import com.example.proyectolp.repository.*;import com.example.proyectolp.service.*;import javafx.collections.FXCollections;import javafx.concurrent.Task;import javafx.fxml.FXML;import javafx.scene.Parent;import javafx.scene.control.*;import javafx.scene.layout.*;import java.time.*;import java.util.*;import java.util.concurrent.*;
public class RewardsController {
 @FXML private Label message,balanceLabel,copLabel,habitsBreakdown,tasksBreakdown,projectsBreakdown,goalsBreakdown,penaltiesBreakdown,xpLabel,levelLabel,rankLabel,nextLevelLabel,streakLabel,penaltyLabel;@FXML private ProgressBar levelProgress;@FXML private ComboBox<String> originFilter;@FXML private TableView<CreditEntry> ledgerTable;@FXML private TableColumn<CreditEntry,String> dateCol,conceptCol;@FXML private TableColumn<CreditEntry,Number> creditsCol;@FXML private FlowPane badgeGrid;@FXML private ListView<String> missionList;
 private final ExecutorService executor=SessionTaskExecutor.get();private List<CreditEntry> ledger=List.of();private Parent dashboardRoot;private DashboardController dashboard;
 @FXML private void initialize(){originFilter.getItems().setAll("Todos","Hábitos","Tareas","Proyectos","Metas","Penalizaciones");originFilter.setValue("Todos");originFilter.setOnAction(e->renderLedger());dateCol.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().created_at==null?"":c.getValue().created_at.toLocalDate().toString()));conceptCol.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().description));creditsCol.setCellValueFactory(c->new javafx.beans.property.SimpleIntegerProperty(c.getValue().credits));load();}
 public void setDashboard(Parent root,DashboardController c){dashboardRoot=root;dashboard=c;}
 private record Data(List<CreditEntry> ledger,List<XpEntry> xp,UserStats stats,Set<String> badges,List<DailyMission> missions){}
 private void load(){message.setText("Cargando…");Task<Data> t=new Task<>(){@Override protected Data call()throws Exception{SupabaseService db=new SupabaseService(AppConfig.load());return new Data(new CreditLedgerRepository(db).list(),new XpLogRepository(db).list(),new UserStatsRepository(db).get(),new UserBadgeRepository(db).list(),new DailyMissionRepository(db).list(LocalDate.now(Clock.system(ZoneId.of("America/Bogota")))));}};t.setOnSucceeded(e->{ledger=t.getValue().ledger;render(t.getValue());message.setText("");});t.setOnFailed(e->message.setText("No se pudieron cargar recompensas. Revisa conexión, esquema y RLS."));executor.submit(t);}
 private void render(Data d){int total=d.ledger.stream().mapToInt(x->x.credits).sum();balanceLabel.setText(total+" créditos");copLabel.setText(java.text.NumberFormat.getCurrencyInstance(Locale.forLanguageTag("es-CO")).format(total*CreditRules.COP_PER_CREDIT));habitsBreakdown.setText("Hábitos: "+sum("habito"));tasksBreakdown.setText("Tareas: "+(sum("tarea")+sum("tarea_proyecto")));projectsBreakdown.setText("Etapas: "+sum("etapa_proyecto"));goalsBreakdown.setText("Metas: "+sum("meta_ahorro"));penaltiesBreakdown.setText("Penalizaciones: "+sum("penalizacion"));renderLedger();int xp=d.xp.stream().mapToInt(x->x.amount).sum(),level=LevelCurve.level(xp);xpLabel.setText(xp+" XP");levelLabel.setText("Nivel "+level);rankLabel.setText("Rango "+LevelCurve.rank(level));levelProgress.setProgress(LevelCurve.progress(xp));nextLevelLabel.setText(LevelCurve.xpToNext(xp)+" XP para el siguiente nivel");streakLabel.setText("Racha actual: "+d.stats.current_streak+" · mejor: "+d.stats.best_streak);penaltyLabel.setText("Si pierdes la racha, tus créditos se dividirán entre "+CreditRules.penaltyDivisor(d.stats.current_streak)+".");badgeGrid.getChildren().clear();BadgeService.CATALOG.forEach((code,name)->{boolean unlocked=d.badges.contains(code);Label tile=new Label((unlocked?"🏅 ":"🔒 ")+name);tile.setStyle("-fx-padding: 14; -fx-border-color: #d9dee7; -fx-border-radius: 6;");badgeGrid.getChildren().add(tile);});missionList.setItems(FXCollections.observableArrayList(d.missions.stream().map(m->(m.completed?"✓ ":"")+m.description+" · "+m.progress+"/"+m.target+" · "+m.xp_reward+" XP").toList()));}
 private int sum(String type){return ledger.stream().filter(e->e.entry_type.equals(type)).mapToInt(e->e.credits).sum();}
 private void renderLedger(){if(ledgerTable==null)return;String f=originFilter.getValue();List<CreditEntry> rows=ledger.stream().filter(e->f==null||f.equals("Todos")||switch(f){case "Hábitos"->e.entry_type.equals("habito");case "Tareas"->e.entry_type.startsWith("tarea");case "Proyectos"->e.entry_type.equals("etapa_proyecto");case "Metas"->e.entry_type.equals("meta_ahorro");case "Penalizaciones"->e.entry_type.equals("penalizacion");default->true;}).toList();ledgerTable.setItems(FXCollections.observableArrayList(rows));}
 @FXML private void back(){if(dashboardRoot!=null){ledgerTable.getScene().setRoot(dashboardRoot);if(dashboard!=null)dashboard.refrescar();}}
}
